Bash(ssh root@46.202.150.64 "docker exec prevencao-backend-prod node -e ""
const { AppDataSource } = require\(''./dist/config/database''\);
const { RuptureSurveyItem } = require\(''./dist/entities/RuptureSurveyItem''\);

AppDataSource.initialize\(\).then\(async \(\) => {
  const itemRepo = AppDataSource.getRepository\(RuptureSurveyItem\);

  // Buscar todos os itens de ruptura do período
  const items = await itemRepo
    .createQueryBuilder\(''item''\)
    .innerJoin\(''rupture_surveys'', ''survey'', ''survey.id = item.survey_id''\)
    .where\(''survey.data_criacao >= :dataInicio'', { dataInicio: ''2025-12-03'' }\)
    .andWhere\(''survey.data_criacao <= :dataFim'', { dataFim: ''2026-01-02 23:59:59'' }\)
    .andWhere\(''\(item.status_verificacao = :nao_encontrado OR item.status_verificacao = :ruptura_estoque\)'', 
      { nao_encontrado: ''nao_encontrado'', ruptura_estoque: ''ruptura_estoque'' }\)
    .select\([''item.descricao'', ''item.status_verificacao'']\)
    .getMany\(\);

  console.log\(''Total de itens com ruptura:'', items.length\);
  console.log\(''\\nProdutos únicos:''\);

  const produtos = {};
  items.forEach\(item => {
    if \(!produtos[item.descricao]\) {
      produtos[item.descricao] = {
        nao_encontrado: 0,
        ruptura_estoque: 0,
        total: 0
      };
    }
    produtos[item.descricao].total++;
    if \(item.status_verificacao === ''nao_encontrado''\) {
      produtos[item.descricao].nao_encontrado++;
    } else {
      produtos[item.descricao].ruptura_estoque++;
    }
  }\);

  Object.entries\(produtos\).forEach\(\([desc, counts]\) => {
    console.log\(desc + '':'', counts\);
  }\);

  await AppDataSource.destroy\(\);
  process.exit\(0\);
}\).catch\(err => {
  console.error\(err\);
  process.exit\(1\);
}\);
""")

